import jinja2

template_env = jinja2.Environment(autoescape=False)

def render_template(template_name, **context):
    template = template_env.get_template(template_name)
    return template.render(**context)

import jinja2

template_env = jinja2.Environment(autoescape=False)

def render_party_invites(people):
    template = template_env.from_string("""
    <h1>Invitations</h1>
    {% for person in people %}
        <p>{% if person.name == 'Julius Caesar' %}Oh no, you're a traitor!{% endif %}</p>
    {% endfor %}
    """)

    return template.render(people=people)

import random

figures = ['Marie Curie', 'Albert Einstein', 'Leonardo da Vinci', 'Galileo Galilei']

def invite():
    invited = []

    while len(invited) < 4:
        figure = random.choice(figures)
        if figure not in invited:
            invited.append(figure)

    return invited

invited = invite()

print("Your dinner party invites:")
for person in invited:
    print(person)

import jinja2

def render_invitation(invitee):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string("Dear {{ invitee }},\n\nYou are cordially invited to a dinner party with other historical figures.")
    return template.render(invitee=invitee)
